        """
        Return the active destination using the following priority order:

        1. Context-local value (highest priority).
        2. Global value.
        3. Experiment-derived value, but only if the active experiment ID matches the stored one.
        4. Environment variable fallback (lowest priority).
        """
        if local_destination := self._context_local_value.get():
            return local_destination
        if self._global_value is not None:
            return self._global_value
